INSERT INTO purpose VALUES('theory-probability','distribution::Distribution','struct','Holds a finite distribution in canonical order with exact positive weights that sum to one, so the finite Giry monad, the product, the marginals and the restriction to an event read one form.','measure','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','error::InferenceError','enum','Names why inference refused: a scope, a table, a factor graph, a tree or an elimination order that is not well formed, or a weight past the carrier.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','error::ProbabilityError','enum','Names why an operation on distributions refused: a weight past the integers, a set or an event with no weight, or weights that are not a distribution.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','factor::FactorGraph','struct','Holds the arities of the variables and the tables over them, each variable in a factor known with its arity, so sum-product reads one graph.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','glue::Disagreement','struct','Holds the two members, the overlap and the entry where two local tables sum to different weights, with both weights, as the witness of a failed gluing.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','glue::Family','struct','Holds local tables over a cover and the pairs that overlap, so their gluing and the possibility of a joint are decided on one family.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','glue::Gluing','enum','Names the verdict on a family: the shared table on each overlap, or each disagreement with its entry and both weights.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','glue::Possibility','enum','Names whether each entry of positive weight extends to a world every member admits, or the first member and entry that does not.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','joint::Independence','enum','Names the verdict on a joint distribution: independent, or the first pair whose weight is not the product of its marginal weights.','nominal','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','junction::Assignment','struct','Holds one value for each variable of a graph, as the decoded assignment of greatest weight.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','junction::Calibrated','struct','Holds the belief of each clique after sum-product, as a family over the tree, so a marginal reads from one clique.','measure','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','junction::JunctionTree','struct','Holds the cliques of a graph joined by a tree with the running intersection property, so sum-product sends one message each way on each edge.','measure','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','semiring::MaxTimes','struct','Holds the max-times semiring over the non-negative rationals, so sum-product gives the greatest weight of each assignment.','measure','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','semiring::Probability','struct','Holds the probability semiring over the non-negative rationals, so sum-product gives the marginal of each clique.','measure','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','table::Arity','struct','Holds the number of values of a variable.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','table::Scope','struct','Holds variables in ascending order with their arities and strides, so an entry decodes to the value of each variable.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','table::Table','struct','Holds one weight for each assignment of a scope, the last variable fastest, so a marginal is one stride walk.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','table::Value','struct','Holds one value of a variable, below its arity.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-probability','table::Variable','struct','Holds a variable of a factor graph by its number.',NULL,'fits','sound',NULL);
